st.title("📊 Online Shopping Platform Performance Dashboard")
st.caption("Online shopping sales, revenue, customers, returns and inventory analysis")

# -----------------------------
# Prepare data
# -----------------------------
raw = DATA.get("raw", [])
df = pd.DataFrame(raw)

# Map likely source fields from the embedded dashboard structure
if not df.empty:
    rename_map = {
        "plat": "Platform",
        "units": "Units",
        "rev": "Revenue",
        "ret": "Returned",
        "stock": "Stock",
        "rating": "Rating",
        "cust": "Customer",
        "prod": "Product",
        "ym": "YearMonth",
        "yr": "Year",
        "reason": "ReturnReason",
    }
    df = df.rename(columns={k: v for k, v in rename_map.items() if k in df.columns})

# -----------------------------
# Filters
# -----------------------------
st.sidebar.header("Filters")

if "Platform" in df.columns:
    platforms = sorted(df["Platform"].dropna().unique())
    selected_platforms = st.sidebar.multiselect(
        "Platform",
        platforms,
        default=platforms
    )
    filtered = df[df["Platform"].isin(selected_platforms)].copy()
else:
    filtered = df.copy()

if "Year" in filtered.columns:
    years = sorted(filtered["Year"].dropna().unique())
    selected_years = st.sidebar.multiselect("Year", years, default=years)
    filtered = filtered[filtered["Year"].isin(selected_years)]

# -----------------------------
# KPI calculations
# -----------------------------
orders = len(filtered)
units = filtered["Units"].sum() if "Units" in filtered.columns else 0
revenue = filtered["Revenue"].sum() if "Revenue" in filtered.columns else 0
aov = revenue / orders if orders else 0

if "Returned" in filtered.columns:
    return_rate = filtered["Returned"].sum() / orders * 100 if orders else 0
else:
    return_rate = 0

if "Stock" in filtered.columns:
    stock_out_rate = (filtered["Stock"] == 0).mean() * 100 if orders else 0
else:
    stock_out_rate = 0

customers = filtered["Customer"].nunique() if "Customer" in filtered.columns else 0
rating = filtered["Rating"].mean() if "Rating" in filtered.columns else 0

k1, k2, k3, k4, k5 = st.columns(5)
k1.metric("Total Orders", f"{orders:,}")
k2.metric("Products Sold", f"{units:,.0f}")
k3.metric("Total Revenue", f"₹{revenue:,.0f}")
k4.metric("Avg Order Value", f"₹{aov:,.0f}")
k5.metric("Return Rate", f"{return_rate:.1f}%")

st.divider()

# -----------------------------
# Platform analysis
# -----------------------------
if "Platform" in filtered.columns:
    grouped = filtered.groupby("Platform", as_index=False).agg(
        Orders=("Platform", "size"),
        Units=("Units", "sum") if "Units" in filtered.columns else ("Platform", "size"),
        Revenue=("Revenue", "sum") if "Revenue" in filtered.columns else ("Platform", "size"),
        Customers=("Customer", "nunique") if "Customer" in filtered.columns else ("Platform", "size"),
        Rating=("Rating", "mean") if "Rating" in filtered.columns else ("Platform", "size"),
    )

    if "Returned" in filtered.columns:
        returns_by_platform = filtered.groupby("Platform")["Returned"].sum()
        grouped["Return Rate"] = grouped.apply(
            lambda r: (returns_by_platform.get(r["Platform"], 0) / r["Orders"] * 100)
            if r["Orders"] else 0,
            axis=1
        )

    if "Stock" in filtered.columns:
        stockouts = filtered.groupby("Platform")["Stock"].apply(lambda x: (x == 0).sum())
        grouped["Stock Out Rate"] = grouped.apply(
            lambda r: (stockouts.get(r["Platform"], 0) / r["Orders"] * 100)
            if r["Orders"] else 0,
            axis=1
        )

    c1, c2 = st.columns(2)

    with c1:
        st.subheader("Platform vs Units Sold")
        fig = px.bar(grouped, x="Platform", y="Units", text_auto=".2s")
        st.plotly_chart(fig, use_container_width=True)

    with c2:
        st.subheader("Platform vs Revenue")
        fig = px.bar(grouped, x="Platform", y="Revenue", text_auto=".2s")
        st.plotly_chart(fig, use_container_width=True)

    c3, c4 = st.columns(2)

    with c3:
        st.subheader("Customer Satisfaction")
        fig = px.bar(grouped, x="Platform", y="Rating", text_auto=".2f")
        st.plotly_chart(fig, use_container_width=True)

    with c4:
        if "Return Rate" in grouped.columns:
            st.subheader("Return Rate by Platform")
            fig = px.bar(grouped, x="Platform", y="Return Rate", text_auto=".1f")
            st.plotly_chart(fig, use_container_width=True)

# -----------------------------
# Yearly revenue
# -----------------------------
if "Year" in filtered.columns and "Revenue" in filtered.columns:
    st.subheader("Yearly Revenue Comparison")
    yearly = filtered.groupby("Year", as_index=False)["Revenue"].sum()
    fig = px.bar(yearly, x="Year", y="Revenue", text_auto=".2s")
    st.plotly_chart(fig, use_container_width=True)

# -----------------------------
# Monthly trend
# -----------------------------
if "YearMonth" in filtered.columns and "Revenue" in filtered.columns:
    st.subheader("Monthly Sales & Revenue Trend")
    trend = filtered.groupby("YearMonth", as_index=False).agg(
        Revenue=("Revenue", "sum"),
        Units=("Units", "sum") if "Units" in filtered.columns else ("Revenue", "size")
    )

    fig = px.line(
        trend,
        x="YearMonth",
        y="Revenue",
        markers=True,
        title="Monthly Revenue Trend"
    )
    st.plotly_chart(fig, use_container_width=True)

# -----------------------------
# Revenue contribution
# -----------------------------
if "Platform" in filtered.columns and "Revenue" in filtered.columns:
    st.subheader("Revenue Contribution by Platform")
    platform_revenue = filtered.groupby("Platform", as_index=False)["Revenue"].sum()
    fig = px.pie(
        platform_revenue,
        names="Platform",
        values="Revenue",
        hole=0.45
    )
    st.plotly_chart(fig, use_container_width=True)

# -----------------------------
# Return reasons
# -----------------------------
if "Returned" in filtered.columns and "ReturnReason" in filtered.columns:
    returned = filtered[
        (filtered["Returned"] == 1) &
        filtered["ReturnReason"].notna()
    ]

    if not returned.empty:
        st.subheader("Return Reasons Breakdown")
        reasons = returned["ReturnReason"].value_counts().reset_index()
        reasons.columns = ["Reason", "Count"]
        fig = px.bar(reasons, x="Reason", y="Count", text_auto=True)
        st.plotly_chart(fig, use_container_width=True)

# -----------------------------
# Inventory / stock
# -----------------------------
if "Stock" in filtered.columns:
    c1, c2 = st.columns(2)

    with c1:
        st.subheader("Stock Availability by Platform")
        stock_platform = filtered.groupby("Platform").agg(
            Stock_Availability=("Stock", lambda x: (x > 0).mean() * 100)
        ).reset_index()
        fig = px.bar(
            stock_platform,
            x="Platform",
            y="Stock_Availability",
            labels={"Stock_Availability": "Availability %"},
            text_auto=".1f"
        )
        st.plotly_chart(fig, use_container_width=True)

    with c2:
        if "Product" in filtered.columns:
            st.subheader("Top Out-of-Stock / Low-Stock Products")
            stock_table = (
                filtered.groupby(["Product", "Platform"])
                .agg(
                    Stock_Outs=("Stock", lambda x: (x == 0).sum()),
                    Minimum_Stock=("Stock", "min")
                )
                .reset_index()
                .sort_values("Stock_Outs", ascending=False)
                .head(8)
            )
            stock_table["Status"] = stock_table["Minimum_Stock"].apply(
                lambda x: "Out of Stock" if x == 0
                else ("Low Stock" if x < 10 else "In Stock")
            )
            st.dataframe(stock_table, use_container_width=True, hide_index=True)

# -----------------------------
# Platform summary
# -----------------------------
if "Platform" in filtered.columns:
    st.subheader("Platform Performance Summary")
    display_cols = [
        c for c in [
            "Platform", "Orders", "Units", "Revenue",
            "Customers", "Rating", "Return Rate", "Stock Out Rate"
        ] if c in grouped.columns
    ]
    st.dataframe(
        grouped[display_cols].sort_values("Revenue", ascending=False),
        use_container_width=True,
        hide_index=True
    )

st.caption(
    f"Dashboard generated from {orders:,} filtered orders. "
    "Use the sidebar filters to interact with the analysis."
)
